lines = ["cat dog cat", "dog", "cat"]
def mapper(line):
    return [(w, 1) for w in line.split()]
def combiner(pairs):
    out = {}
    for k, v in pairs:
        out[k] = out.get(k, 0) + v
    return list(out.items())
combined = []
for line in lines:
    combined += combiner(mapper(line))
groups = {}
for k, v in combined:
    groups.setdefault(k, []).append(v)
for k in sorted(groups):
    print(k, sum(groups[k]))
print("total", sum(sum(v) for v in groups.values()))
